import json,html
from pathlib import Path
b=Path(__file__).parent;a=b/'assets';cuts=json.loads((a/'proposed-cuts.json').read_text())['cuts'];sil=json.loads((a/'source.silence-edl.json').read_text());fmt=lambda t:f'{int(t//60):02d}:{t%60:05.2f}'
md=['# Proposed mistake cuts','',f'Order: **1.mov → 2.mov**. Original 22:52.13; silence-only edit 14:29.76. {len(cuts)} proposed mistake cuts remove a further {sum(c["end"]-c["start"] for c in cuts):.1f} seconds after silence trimming.','', 'Recommendation: apply all 37. Keep intentional emphasis, complete explanations, and the speaker’s final corrected takes.','', '| # | Source time | Remove | Keep following |','|---|---|---|---|']
rows=[]
for i,c in enumerate(cuts,1):
 md.append(f'| {i} | {fmt(c["source_start"])} | {c["removes"]} | {c["keeps"]} |');rows.append(f'<tr><td>{i}</td><td><button data-t="{max(0,c["source_start"]-1.5)}">{fmt(c["source_start"])}</button></td><td>{html.escape(c["removes"])}</td><td>{html.escape(c["keeps"])}</td></tr>')
md+=['','Source timecodes refer to the combined recording. Cut 7 removes the unrelated line “We can change our names if you want” during the long wait. Cut 21 retains the spoken correction “from 2024, 2025, I believe.”','', 'Mechanical candidates “super, super good” and “access to to actually start” are intentionally kept.']
(b/'CUT-REVIEW.md').write_text('\n'.join(md)+'\n')
(b/'review.html').write_text('''<!doctype html><meta charset="utf-8"><title>Blender tutorial — cut review</title><style>body{background:#111820;color:#e7edf6;font:16px/1.5 system-ui;max-width:1250px;margin:40px auto;padding:0 24px}video{width:100%;position:sticky;top:0;max-height:42vh;background:black}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #344050;text-align:left;vertical-align:top}button,a{color:#99cfff}button{background:#223349;border:1px solid #527093;border-radius:5px;padding:5px;cursor:pointer}h1{font-size:28px}.sub{color:#a9b7c8}</style><h1>Blender tutorial — proposed mistake cuts</h1><p class="sub">1.mov → 2.mov · 37 reviewed cuts · Click a time to play the original with context.</p><p><a href="CUT-REVIEW.md">Written recommendations</a></p><video id="v" src="assets/source.mov" controls preload="metadata"></video><table><thead><tr><th>#</th><th>Source</th><th>Remove</th><th>Keep following</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><script>const v=document.getElementById('v');document.querySelectorAll('button').forEach(b=>b.onclick=()=>{v.currentTime=Number(b.dataset.t);v.play()})</script>''')
print('\n'.join(md[:7]));print('Review ready:',b/'CUT-REVIEW.md')
